def date_bce(earliest, latest, label, basis, kind="earliest-attested-phase"):
    return dict(earliest=earliest, latest=latest, date_label=label, basis=basis, kind=kind)


def town(tid, name, country, lat, lon, earliest, mature, late, status, relation, summary, sources,
         gaps, *, civic, urban, hiatus, spans=None, regional=None, category="living-town-candidate",
         site=None, anchors=None):
    return dict(id=tid, name=name, country=country, lat=lat, lon=lon,
                coordinate_precision=dict(meters=5000, basis="Project-authored approximate geographic index point, rounded to 0.01 degree; not a surveyed centre or ancient boundary.", anchor_kind="modern-town-or-named-place"),
                category=category, modern_civic_identity=civic,
                evidence_place=site or name, earliest_evidence_bce=earliest,
                earlier_regional_evidence=regional or [], urban_foundation=urban,
                occupation_spans=spans or [], indus_overlap=dict(mature_2600_1900=mature, late_1900_1300=late,
                    basis="Coded only for evidence at the named evidence_place. A nearby site is listed separately. Contemporaneity does not assign Indus cultural affiliation."),
                continuity_status=status, indus_to_present_demonstrated=False,
                spatial_relation=relation, known_hiatuses=hiatus,
                summary=summary, source_ids=sources, gaps=gaps,
                chronology_anchors=anchors or [])


