def write_json(name, value):
    (HERE / name).write_text(json.dumps(value, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def main():
    write_json("sources.json", dict(schema_version="1.0", created_date=DATE, sources=SOURCES,
                                    source_scope="Authored source pointers and observations. Acquired third-party bytes remain local-only.",
                                    acquisition_manifests=["acquisition-v1.json", "acquisition-v2.json"]))
    write_json("towns.json", dict(schema_version="1.0", created_date=DATE,
                                 scope="Purposive source review of sixteen living-town or modern-settlement candidates in five present countries, with two abandoned Indus contrasts. Not an exhaustive oldest-town ranking.",
                                 periods=dict(mature_indus_bce=[2600, 1900], late_harappan_comparison_bce=[1900, 1300]),
                                 date_convention="Positive BCE numbers; earliest >= latest. A phase range is not a confidence interval for a founding date. CE and uncalibrated results remain labelled in separate fields.",
                                 coordinate_scope="All 18 main pins are approximate regional index points with 5 km stated precision; inspect the spatial relation before using them as evidence locations.",
                                 records=TOWNS))
    text_field = {"type": "string", "minLength": 1}
    text_list = {"type": "array", "items": text_field}
    record_schema = {
        "type": "object",
        "required": ["id", "name", "country", "lat", "lon", "coordinate_precision", "category", "modern_civic_identity", "evidence_place", "earliest_evidence_bce", "earlier_regional_evidence", "urban_foundation", "occupation_spans", "indus_overlap", "continuity_status", "indus_to_present_demonstrated", "spatial_relation", "known_hiatuses", "summary", "source_ids", "gaps", "chronology_anchors"],
        "properties": {**{k: text_field for k in ["id", "name", "country", "modern_civic_identity", "evidence_place", "urban_foundation", "continuity_status", "spatial_relation", "summary"]},
            "lat": {"type": "number", "minimum": -90, "maximum": 90},
            "lon": {"type": "number", "minimum": -180, "maximum": 180},
            "coordinate_precision": {"type": "object", "required": ["meters", "basis", "anchor_kind"], "properties": {"meters": {"type": "number", "exclusiveMinimum": 0}, "basis": text_field, "anchor_kind": text_field}},
            "category": {"enum": ["living-town-candidate", "abandoned-indus-contrast"]},
            "earliest_evidence_bce": {"type": "object", "required": ["earliest", "latest", "date_label", "basis", "kind"], "properties": {"earliest": {"type": ["integer", "null"], "minimum": 1}, "latest": {"type": ["integer", "null"], "minimum": 1}, "date_label": text_field, "basis": text_field, "kind": text_field}},
            "earlier_regional_evidence": {"type": "array", "items": {"type": "object", "required": ["place", "date_label", "relationship", "source_ids"]}},
            "occupation_spans": {"type": "array", "items": {"type": "object", "required": ["start_bce", "end_bce", "scope"], "properties": {"start_bce": {"type": "integer", "minimum": 1}, "end_bce": {"type": "integer", "minimum": 1}, "scope": text_field}}},
            "indus_overlap": {"type": "object", "required": ["mature_2600_1900", "late_1900_1300", "basis"], "properties": {"mature_2600_1900": {"enum": ["yes", "no", "uncertain"]}, "late_1900_1300": {"enum": ["yes", "no", "uncertain"]}, "basis": text_field}},
            "indus_to_present_demonstrated": {"type": "boolean", "description": "True requires an independently reviewed complete local occupation series. All records in version 1 are false."},
            "known_hiatuses": text_list, "source_ids": {"type": "array", "minItems": 1, "uniqueItems": True, "items": {"type": "string", "pattern": "^LT-S[0-9]{2}$"}},
            "gaps": {"type": "array", "minItems": 1, "items": text_field},
            "chronology_anchors": {"type": "array", "items": {"type": "object", "required": ["date_label", "status", "basis", "source_ids"]}}},
    }
    write_json("towns.schema.json", {"$schema": "https://json-schema.org/draft/2020-12/schema", "title": "Living towns source register 1.0", "type": "object", "required": ["schema_version", "created_date", "scope", "periods", "records"], "properties": {"schema_version": {"const": "1.0"}, "records": {"type": "array", "items": record_schema}}, "description": "Structural schema. validate.py also checks sources, local hashes, chronology, geographic joins and declared gaps."})
    rows = ["# Evidence table: living towns and Indus-period occupation", "",
            "Sixteen candidates and two abandoned-city comparisons. Dates apply to the named evidence place. A nearby older settlement is recorded separately. The map points are approximate; the table supplies no excavation boundaries.", "",
            "| Place | Earliest evidence adopted | Mature / Late overlap | Continuity and spatial evidence | Sources |",
            "|---|---|---|---|---|"]
    byid = {s["id"]: s for s in SOURCES}
    for t in TOWNS:
        links = ", ".join(f'[{sid}]({byid[sid]["url"]})' for sid in t["source_ids"])
        rows.append(f'| {t["name"]}, {t["country"]} | {t["earliest_evidence_bce"]["date_label"]} | {t["indus_overlap"]["mature_2600_1900"]} / {t["indus_overlap"]["late_1900_1300"]} | {t["summary"]} | {links} |')
    rows += ["", "The `no` overlap label means the reviewed local sequence begins later; it is not proof that all earlier deposits are absent. `uncertain` marks an unresolved date or spatial join. The two Indus intervals end at 1900 and 1300 BCE; approximate dates near a boundary require their own dating review.", "",
             "The JSON register carries the civic identity, dated place, urban-development assertion, source access depth, known gaps and prospective evidence for every row.", ""]
    (HERE / "TABLE.md").write_text("\n".join(rows), encoding="utf-8")
    print(json.dumps(dict(records=len(TOWNS), sources=len(SOURCES), files=["towns.json", "sources.json", "towns.schema.json", "TABLE.md"])))


if __name__ == "__main__":
    main()
